#include <sstream>
#include <string>

bool parseValue(const std::string& token, int& value) {
    std::istringstream input{token};
    if (!(input >> value) || value < -1000 || value > 1000) {
        return false;
    }
    input >> std::ws;
    return input.eof();
}

